import {facetPicker} from '../facet-picker.mjs';
import {PALETTES,CONFIGURATIONS,cityPreset} from './city-settings.mjs';
export function hexLayoutIcon(layout){const hex=(x,y)=>`<polygon points="${x},${y-8} ${x+7},${y-4} ${x+7},${y+4} ${x},${y+8} ${x-7},${y+4} ${x-7},${y-4}"/>`;return `<svg viewBox="0 0 54 38" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6">${layout==='single'?hex(27,19):layout==='line'?hex(11,19)+hex(27,19)+hex(43,19):hex(19,11)+hex(35,11)+hex(27,25)}</svg>`;}
export function cityUI({getActive,regenerate,scenes,fit,place}){
 if(document.querySelector('#city-panel'))return;
 const panel=document.createElement('aside');panel.id='city-panel';panel.setAttribute('aria-label','Futurama diorama options');
 panel.innerHTML=`<div class="city-actions"><strong>DIORAMA</strong><button id="city-fit">Fit</button><button id="city-close" aria-label="Close city controls">×</button></div>
 <div class="city-config"><button id="city-preset" aria-label="Choose city configuration">Configurations</button><button id="city-layout" aria-label="Choose hex layout"></button></div>
 <div class="city-palette-row"><div id="city-palette" aria-label="City color dial"></div><div><b id="city-palette-name"></b><small>Color facet</small><small id="city-hex-count"></small></div></div>
 <div id="city-sliders"></div><label class="city-check"><input id="city-mirror" type="checkbox"> Mirror facades</label>
 <div class="city-actions"><button id="city-place">Place in Sandbox</button><button id="city-scenes">Scenes</button></div>
 <p id="city-population" class="city-note"></p><details><summary>About this diorama</summary><p>A retro-future visual playground using the same 30-piece kit. People walk and couriers move finite parcels. Airships and cars are decorative circuits. No city economy, jobs, needs, or passenger transport.</p><p>Changing a facet rebuilds the layout and restarts parcel activity. Saved scenes retain their facets and activity.</p><p id="city-ledger"></p></details>`;
 document.body.append(panel);panel.querySelector('#city-scenes').onclick=scenes;panel.querySelector('#city-fit').onclick=fit;panel.querySelector('#city-close').onclick=()=>{panel.classList.remove('city-open');fit();};panel.querySelector('#city-place').onclick=place;
 facetPicker(panel.querySelector('#city-preset'),{name:'City configuration',choices:CONFIGURATIONS,value:()=>'',choose:id=>regenerate(cityPreset(id)),render:(id,label)=>hexLayoutIcon(cityPreset(id).layout)+`<span>${label}</span>`});
 facetPicker(panel.querySelector('#city-layout'),{name:'Hex layout',choices:[['single','One hex'],['triangle','Three hex cluster'],['line','Three hex boulevard']],value:()=>getActive()?.plan.settings.layout,choose:layout=>regenerate({layout}),render:(id,label)=>hexLayoutIcon(id)+`<span>${label}</span>`});
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 120 120');svg.setAttribute('role','group');svg.setAttribute('aria-label','Color facets');
 PALETTES.forEach((p,i)=>{const angle=j=>(j*60-90)*Math.PI/180,pt=j=>[60+54*Math.cos(angle(j)),60+54*Math.sin(angle(j))];const g=document.createElementNS(svg.namespaceURI,'g');g.dataset.palette=p.id;g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label',p.name+' palette');g.innerHTML=`<polygon points="60,60 ${pt(i)} ${pt(i+1)}" fill="${p.colors[2]}" stroke="${p.colors[0]}" stroke-width="3"/><circle cx="${60+33*Math.cos(angle(i+.5))}" cy="${60+33*Math.sin(angle(i+.5))}" r="4" fill="${p.colors[4]}"/>`;g.onclick=()=>regenerate({palette:p.id});g.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();g.onclick();}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();svg.children[(i+(e.key==='ArrowRight'?1:5))%6].focus();}};svg.append(g);});panel.querySelector('#city-palette').append(svg);
 const sliders=[['complexity','Density',1,3,1],['height','Tower height',.65,1.45,.05],['noise','Skyline noise',0,1,.05],['combine','Rooftop combinations',0,1,.05],['airships','Airships',0,8,1],['traffic','Street traffic',0,12,1]];
 for(const [key,label,min,max,step]of sliders){const row=document.createElement('label');row.className='city-range';row.innerHTML=`<span>${label}</span><output id="city-${key}-value"></output><input id="city-${key}" aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}" data-city-setting="${key}">`;const input=row.querySelector('input');input.oninput=()=>row.querySelector('output').textContent=format(key,+input.value);input.onchange=()=>regenerate({[key]:+input.value});panel.querySelector('#city-sliders').append(row);}
 panel.querySelector('#city-mirror').onchange=e=>regenerate({mirror:e.target.checked});
 const toggle=document.createElement('button');toggle.id='city-controls';toggle.textContent='Facets';toggle.setAttribute('aria-label','Diorama facets');toggle.onclick=()=>{panel.classList.toggle('city-open');fit();};(document.querySelector('#toolbar-tools')||document.querySelector('header')).append(toggle);
 const style=document.createElement('style');style.textContent=`#city-panel,#city-controls{display:none}body[data-family=city] #city-controls{display:inline-flex}body[data-family=city] #city-panel{display:block;position:fixed;right:12px;top:70px;width:270px;max-height:calc(100dvh - 82px);overflow:auto;overscroll-behavior:contain;z-index:35;padding:14px;border-radius:16px;background:var(--app-paper,#fff9ec);color:var(--app-ink,#433c2b);font:12px Manrope,sans-serif;box-sizing:border-box}#city-panel button{font:inherit;min-height:36px}#city-panel p{line-height:1.5}.city-actions{display:flex;align-items:center;gap:8px}.city-actions strong{font-size:10px;letter-spacing:.16em;margin-right:auto;color:var(--app-accent,#b84931)}#city-close{display:none}.city-config{display:flex;gap:8px;margin:12px 0}.city-config button:first-child{flex:1}#city-layout{width:64px}#city-layout svg,.facet-picker svg{width:48px;height:34px}.city-palette-row{display:flex;align-items:center;gap:14px}.city-palette-row small{display:block;margin-top:5px;opacity:.7}#city-palette svg{width:108px;height:108px;overflow:visible}#city-palette g{cursor:pointer;outline:none}#city-palette g[aria-pressed=true] polygon{stroke:var(--app-ink,#433c2b);stroke-width:5}#city-palette g:focus polygon{stroke:#fff;stroke-width:6}.city-range{display:grid;grid-template-columns:1fr auto;gap:3px;margin:9px 0}.city-range input{grid-column:1/-1;width:100%;height:18px;accent-color:var(--app-accent,#b84931)}.city-check{display:flex;align-items:center;gap:7px;margin:10px 0}.city-note{font-size:11px;opacity:.75}#city-panel details{font-size:11px}body[data-family=city] #current-scene-type,body[data-family=city] #panel{display:none!important}@media(max-width:700px){body[data-family=city] #city-panel{display:none;top:auto;bottom:10px;left:10px;right:10px;width:auto;max-height:48dvh}body[data-family=city] #city-panel.city-open{display:block}#city-close{display:block}#city-panel input[type=range]{height:28px}}`;
 document.head.append(style);
}
function format(k,v){return k==='height'?v.toFixed(2)+'×':['noise','combine'].includes(k)?Math.round(v*100)+'%':String(v);}
export function updateCityUI(active){const p=document.querySelector('#city-panel');if(!p)return;const o=active.plan.settings,s=active.life.summary();p.querySelector('#city-ledger').textContent=active.life.readout;p.querySelector('#city-population').textContent=`${s.buildings} buildings · ${o.airships} airships · 30-piece kit`;p.querySelector('#city-hex-count').textContent=active.plan.districts.length+' hex'+(active.plan.districts.length>1?'es':'');p.querySelector('#city-palette-name').textContent=PALETTES.find(v=>v.id===o.palette).name;p.querySelector('#city-layout').innerHTML=hexLayoutIcon(o.layout);for(const g of p.querySelectorAll('[data-palette]'))g.setAttribute('aria-pressed',String(g.dataset.palette===o.palette));for(const input of p.querySelectorAll('[data-city-setting]')){if(document.activeElement===input)continue;const k=input.dataset.citySetting;input.value=o[k];p.querySelector('#city-'+k+'-value').textContent=format(k,o[k]);}p.querySelector('#city-mirror').checked=o.mirror;}
